function replicateOrder(orderId, nodes) {
  const acks = [];
  for (const n of nodes) {
    const res = n.send(orderId);
    if (res && res.ok) acks.push(n.id);
  }
  return { orderId, acks, committed: acks.length === nodes.length };
}

module.exports = { replicateOrder };

