const REQUIRED_CHAOS_SCENARIOS = [
  'happy-path',
  'node-death',
  'packet-loss',
  'jitter',
  'cascade-failure'
];

function canPromoteToTrunk(passedScenarios) {
  const set = new Set(passedScenarios);
  return REQUIRED_CHAOS_SCENARIOS.every((s) => set.has(s));
}

module.exports = { REQUIRED_CHAOS_SCENARIOS, canPromoteToTrunk };

